head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

scwin.fn_GetPar, scwin.fn_SetPar;
scwin.TR_JOB;
scwin.vBzProcsNo;
scwin.vSecugrpID = SECUGRP_ID_ST;
scwin.vScrenID = "ULDSTF05268.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_initForm = function(initTyp) {
    if (initTyp == "C") {
        btn_Update.src = "../img/btn_modify_d.gif";
        btn_Update.setDisabled(true);
    } else if (initTyp == "U") {
        btn_Update.src = "../img/btn_modify.gif";
        btn_Update.setDisabled(false);
    } else if (initTyp == "X") {
        btn_Update.src = "../img/btn_modify_d.gif";
        btn_Update.setDisabled(true);
    }
};
scwin.fn_SetComboCode = function() {
    var strCodeYN = "N^N,Y^Y";
    cmb_DIRCTLIST_CORP_YN.CBData = strCodeYN;
    cmb_COND_LIST_YN.CBData = strCodeYN;
    cmb_VENTBZ_YN.CBData = strCodeYN;
    cmb_PEPLSTK_YN.CBData = strCodeYN;
    cmb_SME_YN.CBData = strCodeYN;
    cmb_SPAC_YN.CBData = strCodeYN;

    //주거래은행
    dts_MaintrBkCd.DataID = "/CodeAction.do?method=listInstCd&For=";
    dts_MaintrBkCd.Reset();
};
scwin.fn_searchCode = function() {
    /*
    00685 - 명의개서대행기관
    01213 - 현물종목거래시장
    00755 - 외부감사인코드
    00726 - 소속부유형코드
    01437 - 상장형태분류코드
    */
    var arrCid = [{
        cid: "TRANSSTK_AGNT_CD",
        cnm: "cmb_TRANSSTK_AGNT_CD"
    }, {
        cid: "SPOT_ISU_TRD_MKT_TP_CD",
        cnm: "cmb_SPOT_ISU_TRD_MKT_TP_CD"
    }, {
        cid: "EXT_AUDTR_CD",
        cnm: "cmb_EXT_AUDTR_CD"
    }, {
        cid: "SECT_TP_CD",
        cnm: "cmb_SECT_TP_CD"
    }, {
        cid: "LIST_CLSS_CD",
        cnm: "cmb_LIST_CLSS_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='TRANSSTK_AGNT_CD','SPOT_ISU_TRD_MKT_TP_CD','EXT_AUDTR_CD','SECT_TP_CD','LIST_CLSS_CD','CURR_ISO_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_SearchCd.getValue(); // 발행기관코드값
    arrPar[1] = txb_SearchNm.getValue(); // 발행기관명
    arrPar[2] = scwin.vSecugrpID;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsur = function(arrPar) {
    txb_SearchCd.setValue(arrPar[0].ISUR_CD);
    txb_SearchNm.setValue(arrPar[0].COM_NM);
    scwin.fn_read_sync();
};
scwin.fn_read_sync = function() {
    var url;
    url = "/IssueBook.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=readIssueBook&inputMessageId=LISTING_ISUBOOK_SEARCH_OUT";
    url += "&SECUGRP_ID=" + scwin.vSecugrpID;
    url += "&P_KEY=" + $c.stf.getObjectValue(txb_SearchCd);
    dts_Corp.DataID = encodeURI(url);
    dts_Corp.Reset();
};
scwin.fn_CheckForm = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[회사]를 선택하세요.");
        txb_ISUR_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_SECUGRP_ID) == SECUGRP_ID_ST) {
        if ($c.stf.getObjectValue(edt_CORP_REG_NO) == "") {
            $c.win.alert("[법인등록번호]을 입력하세요.");
            edt_CORP_REG_NO.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_BZ_REG_NO) == "") {
            $c.win.alert("[사업자등록번호]을 입력하세요.");
            edt_BZ_REG_NO.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(cmb_SECUGRP_ID) == SECUGRP_ID_ST) {
        if ($c.stf.getObjectValue(txb_ZIPCD) == "") {
            $c.win.alert("[우편번호]을 선택하세요.");
            txb_ZIPCD.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(cmb_TRANSSTK_AGNT_CD) == "") {
        $c.win.alert("[명의개서대행기관]을 선택하세요.");
        cmb_TRANSSTK_AGNT_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_EXT_AUDTR_CD) == "") {
        $c.win.alert("[외부감사인]을 선택하세요.");
        cmb_EXT_AUDTR_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_CORP_TEL_NO) == "") {
        $c.win.alert("[회사전화번호]을 입력하세요.");
        txb_CORP_TEL_NO.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_MAJ_PROD_NM) == "") {
        $c.win.alert("[주요제품]을 입력하세요.");
        txb_MAJ_PROD_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_MAINTR_BK_CD) == "") {
        $c.win.alert("[주거래은행]을 선택하세요.");
        cmb_MAINTR_BK_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_DIRCTLIST_CORP_YN) == "") {
        $c.win.alert("[직상장법인여부]를 선택하세요.");
        cmb_DIRCTLIST_CORP_YN.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_COND_LIST_YN) == "") {
        $c.win.alert("[조건부상장여부]를 선택하세요.");
        cmb_COND_LIST_YN.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_VENTBZ_YN) == "") {
        $c.win.alert("[벤처기업여부]를 선택하세요.");
        cmb_VENTBZ_YN.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_SME_YN) == "") {
        $c.win.alert("[중소기업여부]를 선택하세요.");
        cmb_SME_YN.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_PEPLSTK_YN) == "") {
        $c.win.alert("[국민주여부]를 선택하세요.");
        cmb_PEPLSTK_YN.focus();
        return false;
    }
    return true;
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if (scwin.fn_CheckForm()) {
        if (!$c.cp.isModified(dts_Corp)) {
            $c.lc.fn_alertNoUpdate();
            return;
        }
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);

        //alert("[bz_procs_no]"+bz_procs_no);
        if (scwin.vBzProcsNo.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            scwin.fn_trs(TR_JOB_UPDATE);
        }
    }
};
scwin.fn_trs = function(trsIdx) {
    trs_Save.Action = $c.lc.fn_encodeNSession("/IssueBook.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&method=updateIssueBook");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Corp)";
    trs_Save.Parameters = "TRS_IDX=" + trsIdx + ",SECUGRP_ID=" + SECUGRP_ID_ST +
        //",SECUGRP_ID=" + getObjectValue(cmb_SECUGRP_ID) + SECUGRP_ID_ST
        ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",ISUR_CD=" + dts_Corp.getCellData(1, "ISUR_CD") + ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_400;
    trs_Save.Post();
};
scwin.fn_setMarketPanelEvent = function(pMarket) {
    if (pMarket == "1") {
        $c.stf.showObj(panel_ISUR_SYMBL, true);
        $c.stf.showObj(panel_SECT_TP_CD, false);
    } else if (pMarket == "2") {
        $c.stf.showObj(panel_ISUR_SYMBL, false);
        $c.stf.showObj(panel_SECT_TP_CD, true);
    }
};
scwin.btn_Search_onclick = function() {
    if ($c.stf.getObjectValue(txb_SearchCd) == "") {
        $c.win.alert("[회사]를 선택하세요.");
        txb_SearchCd.focus();
        return;
    }
    scwin.fn_read_sync();
};
scwin.img_CoSearch_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsur;
    scwin.fn_SetPar = fn_SetParIsur;

    //fn_PopFindCorpChrg(vSecugrpID);
    $c.lc.fn_PopFindCorpChrgSW(scwin.vSecugrpID, "1");
};
scwin.btn_Update_onclick = function() {
    scwin.fn_update();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_Corp_OnLoadError = function() {
    $c.stf.alert_error(dts_Corp);
};
scwin.dts_Corp_OnLoadCompleted = function(rowcount) {
    //alert('[dts_Corp.Status]'+dts_Corp.Status);
    scwin.fn_setMarketPanelEvent($c.stf.getObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD));
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
    //alert(dts_C_All.ErrorMsg);

};
scwin.trs_Save_OnSuccess = function() {
    $c.lc.fn_alertMsg('S');
    // 목록 다시 조회
    scwin.fn_read_sync();
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    $c.libRoundPanel.PanelToGroupBox(panel_Item);
    scwin.fn_setMarketPanelEvent(js_market);
    $c.elw.fn_searchCode();
    scwin.fn_SetComboCode();
};
